import{bt as e,n as t,ot as n,st as r}from"./chunks/framework.CxhjsvYc.js";var i=JSON.parse(`{"title":"Strategy documentation","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/"}],["meta",{"property":"og:title","content":"Strategy documentation | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/"}],["meta",{"name":"twitter:title","content":"Strategy documentation | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/index.md","filePath":"strategies/index.md","lastUpdated":1793950333000}`),a={name:`strategies/index.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="strategy-documentation" tabindex="-1">Strategy documentation <a class="header-anchor" href="#strategy-documentation" aria-label="Permalink to “Strategy documentation”">​</a></h1><p>FD Cal documents strategy behaviour separately for each simulation objective.</p><h2 id="scoped-range" tabindex="-1">Scoped Range <a class="header-anchor" href="#scoped-range" aria-label="Permalink to “Scoped Range”">​</a></h2><p>The supported strategies optimise the selected start and end dates. Their current objective, trade-offs and optimality limits are summarised in the <a href="/FD-Calculator/dev/docs/STRATEGIES.html#scoped-range">strategy guide</a>.</p><h3 id="technical-references" tabindex="-1">Technical references <a class="header-anchor" href="#technical-references" aria-label="Permalink to “Technical references”">​</a></h3><ul><li><a href="/FD-Calculator/dev/docs/strategies/GREEDY.html">Greedy</a> — local SPLIT/CONSOLIDATE/CARRY decisions and option-selection rules.</li><li><a href="/FD-Calculator/dev/docs/strategies/GSS.html">GSS</a> — recursive scoped planning, liquidity-aware waiting and candidate ordering.</li><li><a href="/FD-Calculator/dev/docs/strategies/ABSOLUTE.html">Absolute R</a> — exhaustive scoped branch-and-bound search and optimality proof conditions.</li><li><a href="/FD-Calculator/dev/docs/strategies/ABSOLUTE-PLUS.html">Absolute R+</a> — bounded scoped search, controls and search diagnostics.</li></ul><h3 id="benchmark" tabindex="-1">Benchmark <a class="header-anchor" href="#benchmark" aria-label="Permalink to “Benchmark”">​</a></h3><ul><li><a href="/FD-Calculator/dev/docs/strategies/benchmarks.html#scoped-range">Scoped Range benchmark</a> — measured net-interest response to horizon, capital, account/bank diversity, inflows and eFD eligibility.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p><strong>Status: Under development — no benchmark data available yet.</strong></p><p>Goal mode is disabled and is not currently user-selectable. The intended first Goal optimiser is Absolute R; the other three strategies remain Scoped Range only.</p><ul><li><a href="/FD-Calculator/dev/docs/strategies/goal-mode-rework-plan.html">Goal-mode rework plan</a> — architecture, implementation phases and release gates.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><ul><li><a href="/FD-Calculator/dev/docs/reference/CODEBASE.html">Codebase map</a> — where strategy implementations fit into the application architecture.</li></ul>`,14)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};